 if(!l){main.innerHTML='<h1>Урок не найден</h1><a href="#catalog">Вернуться к урокам</a>';return;}
 current=l;state.last=l.id;save();const exam=isExamLesson(l),sample=l.tests[0],topic=sandbox?null:topicOf(l,lessons);
 const next=sandbox?null:nextOf(l);
